//! Pure renderers: neutral sources → each tool's native format. No I/O here, so every
//! projection is unit-testable and `check` can diff the rendered form against disk.

use crate::model::{Agent, HookFile, MapFile, McpFile, McpServer, PermSet, Tool};
use anyhow::{bail, Context, Result};
use serde_json::{json, Map, Value};

/// Every generated file carries this, followed by the source it came from. Orphan detection
/// matches on it, so it must never change.
pub const GENERATED_MARK: &str = "GENERATED by agent-sync from ";

/// Keep `<!-- only:<tool> -->` … `<!-- /only -->` blocks for `tool`, drop the others, and drop
/// the marker lines themselves. Nesting and unclosed blocks are errors, not guesses.
pub fn filter_only(body: &str, tool: Tool) -> Result<String> {
    let mut out = String::with_capacity(body.len());
    let mut block: Option<String> = None;
    for line in body.split_inclusive('\n') {
        let t = line.trim();
        if let Some(name) = t
            .strip_prefix("<!-- only:")
            .and_then(|r| r.strip_suffix("-->"))
        {
            if block.is_some() {
                bail!("nested <!-- only: --> block");
            }
            let name = name.trim();
            if name != "claude" && name != "agy" {
                bail!("unknown only-block target '{name}'");
            }
            block = Some(name.to_string());
            continue;
        }
        if t == "<!-- /only -->" {
            if block.take().is_none() {
                bail!("<!-- /only --> without an opening block");
            }
            continue;
        }
        match &block {
            Some(b) if b != tool.key() => {}
            _ => out.push_str(line),
        }
    }
    if block.is_some() {
        bail!("unclosed <!-- only: --> block");
    }
    Ok(out)
}

/// A YAML scalar that is valid under strict parsers: a JSON string literal.
fn yq(s: &str) -> String {
    serde_json::to_string(s).unwrap_or_else(|_| format!("{s:?}"))
}

fn yaml_scalar(v: &serde_yaml::Value) -> Result<String> {
    Ok(serde_yaml::to_string(v)?.trim_end().to_string())
}

fn tool_names(map: &MapFile, tool: Tool, neutral: &[String]) -> Result<Vec<String>> {
    let mut out: Vec<String> = Vec::new();
    for t in neutral {
        let name = match (tool, t.strip_prefix("mcp:")) {
            (Tool::Claude, Some(server)) => format!("mcp__{server}"),
            (Tool::Agy, Some(_)) => continue,
            (_, None) => map.tool_name(tool, t)?,
        };
        if !out.contains(&name) {
            out.push(name);
        }
    }
    Ok(out)
}

/// Render one agent for `tool`. Claude: `tools:` as a comma list (its native form). AGY: a YAML
/// sequence, flat `<name>.md` layout (the layout AGY loads).
pub fn render_agent(map: &MapFile, agent: &Agent, tool: Tool) -> Result<String> {
    let f = &agent.front;
    let model = map.model(tool, &f.tier)?;
    let tools = tool_names(map, tool, &f.tools)?;
    let mut s = String::from("---\n");
    s.push_str(&format!("name: {}\n", f.name));
    s.push_str(&format!("description: {}\n", yq(&f.description)));
    match tool {
        Tool::Claude => {
            if !tools.is_empty() {
                s.push_str(&format!("tools: {}\n", tools.join(", ")));
            }
            s.push_str(&format!("model: {model}\n"));
        }
        Tool::Agy => {
            s.push_str(&format!("model: {model}\n"));
            let has_mcp = f.tools.iter().any(|t| t.starts_with("mcp:"));
            let already_set = f.agy.keys().any(|k| k.as_str() == Some("enable_mcp_tools"));
            if has_mcp && !already_set {
                s.push_str("enable_mcp_tools: true\n");
            }
            if !tools.is_empty() {
                s.push_str("tools:\n");
                for t in &tools {
                    s.push_str(&format!("  - {t}\n"));
                }
            }
        }
    }
    let extras = match tool {
        Tool::Claude => &f.claude,
        Tool::Agy => &f.agy,
    };
    for (k, v) in extras {
        let key = k
            .as_str()
            .context("extra front-matter key must be a string")?;
        s.push_str(&format!("{key}: {}\n", yaml_scalar(v)?));
    }
    s.push_str("---\n");
    let origin = if agent.origin.is_empty() {
        format!("sync/agents/{}.md", f.name)
    } else {
        agent.origin.clone()
    };
    s.push_str(&format!(
        "<!-- {GENERATED_MARK}{origin} — edit the source, not this file -->\n"
    ));
    s.push_str(&filter_only(&agent.body, tool)?);
    let (yaml, _) = crate::model::split_front_matter(&s)?;
    validate_agent_frontmatter(yaml, tool)?;
    Ok(s)
}

/// Validate frontmatter schema for a rendered agent according to tool conventions.
pub fn validate_agent_frontmatter(raw_yaml: &str, tool: Tool) -> Result<()> {
    let val: serde_yaml::Value =
        serde_yaml::from_str(raw_yaml).context("invalid YAML in agent front matter")?;

    let name = val
        .get("name")
        .and_then(|v| v.as_str())
        .context("agent front matter missing 'name'")?;
    if name.is_empty() {
        bail!("agent 'name' cannot be empty");
    }

    val.get("description")
        .and_then(|v| v.as_str())
        .context("agent front matter missing 'description'")?;

    val.get("model")
        .and_then(|v| v.as_str())
        .context("agent front matter missing 'model'")?;

    match tool {
        Tool::Claude => {
            if let Some(tools_val) = val.get("tools") {
                let tools_str = tools_val
                    .as_str()
                    .context("Claude 'tools' must be a comma-separated string")?;
                for t in tools_str
                    .split(',')
                    .map(str::trim)
                    .filter(|s| !s.is_empty())
                {
                    if t.starts_with("run_command")
                        || t.starts_with("view_file")
                        || t.starts_with("replace_file_content")
                        || t.starts_with("write_to_file")
                    {
                        bail!("Claude agent '{name}' has AGY-specific tool component '{t}'");
                    }
                }
            }
        }
        Tool::Agy => {
            if let Some(tools_val) = val.get("tools") {
                let seq = tools_val
                    .as_sequence()
                    .context("AGY 'tools' must be a YAML sequence of strings")?;
                const VALID_AGY_TOOLS: &[&str] = &[
                    "view_file",
                    "run_command",
                    "replace_file_content",
                    "write_to_file",
                ];
                for item in seq {
                    let t = item
                        .as_str()
                        .context("tool in AGY tools list must be a string")?;
                    if t == "call_mcp_tool" {
                        bail!("AGY agent '{name}' specifies 'call_mcp_tool' in tools:; use 'enable_mcp_tools: true' instead");
                    }
                    if !VALID_AGY_TOOLS.contains(&t) {
                        bail!("AGY agent '{name}' contains unknown tool component '{t}'");
                    }
                }
            }
            if let Some(enable_mcp) = val.get("enable_mcp_tools") {
                if !enable_mcp.is_bool() {
                    bail!("AGY agent '{name}' 'enable_mcp_tools' must be boolean");
                }
            }
        }
    }
    Ok(())
}

/// Expand `${NAME}` ONLY for names in `allowed`; every other `${...}` stays verbatim.
pub fn expand_placeholders(
    s: &str,
    allowed: &[String],
    lookup: &dyn Fn(&str) -> Option<String>,
) -> Result<String> {
    let mut out = s.to_string();
    for name in allowed {
        let token = format!("${{{name}}}");
        if out.contains(&token) {
            let val = lookup(name).filter(|v| !v.is_empty()).with_context(|| {
                format!("placeholder ${{{name}}} is not set in the environment")
            })?;
            out = out.replace(&token, &val);
        }
    }
    Ok(out)
}

/// The JSON object one MCP server renders to for `tool`. stdio servers have the same shape in
/// both tools; an HTTP server is `{"type":"http","url"}` for Claude and `{"serverUrl"}` for AGY.
pub fn render_mcp_server(
    srv: &McpServer,
    tool: Tool,
    allowed: &[String],
    lookup: &dyn Fn(&str) -> Option<String>,
) -> Result<Value> {
    let mut o = Map::new();
    if let Some(url) = &srv.url {
        let url = expand_placeholders(url, allowed, lookup)?;
        match tool {
            Tool::Claude => {
                o.insert("type".into(), json!("http"));
                o.insert("url".into(), json!(url));
            }
            Tool::Agy => {
                o.insert("serverUrl".into(), json!(url));
            }
        }
        return Ok(Value::Object(o));
    }
    if let Some(k) = &srv.kind {
        o.insert("type".into(), json!(k));
    }
    let command = srv.command.as_deref().unwrap_or_default();
    o.insert(
        "command".into(),
        json!(expand_placeholders(command, allowed, lookup)?),
    );
    let args = srv
        .args
        .iter()
        .map(|a| expand_placeholders(a, allowed, lookup))
        .collect::<Result<Vec<_>>>()?;
    if !args.is_empty() {
        o.insert("args".into(), json!(args));
    }
    if !srv.env.is_empty() {
        let mut env = Map::new();
        for (k, v) in &srv.env {
            env.insert(k.clone(), json!(expand_placeholders(v, allowed, lookup)?));
        }
        o.insert("env".into(), Value::Object(env));
    }
    Ok(Value::Object(o))
}

/// Canonical form for comparing a registered server with the rendered one: an empty `args` or
/// `env` means the same as an absent one (Claude and AGY each keep one form or the other).
pub fn normalize_server(v: &Value) -> Value {
    let mut v = v.clone();
    if let Some(o) = v.as_object_mut() {
        for k in ["args", "env"] {
            let empty = o.get(k).is_some_and(|x| {
                x.as_array().is_some_and(Vec::is_empty) || x.as_object().is_some_and(Map::is_empty)
            });
            if empty {
                o.remove(k);
            }
        }
    }
    v
}

/// name → rendered server, for the servers that apply to `tool`.
pub fn render_mcp(
    mcp: &McpFile,
    tool: Tool,
    allowed: &[String],
    lookup: &dyn Fn(&str) -> Option<String>,
) -> Result<Map<String, Value>> {
    let mut out = Map::new();
    for (name, srv) in &mcp.servers {
        if srv.applies_to(tool) {
            out.insert(name.clone(), render_mcp_server(srv, tool, allowed, lookup)?);
        }
    }
    Ok(out)
}

/// Render one permission direction for `tool`, de-duplicated, in source order.
pub fn render_perms(set: &PermSet, tool: Tool) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut push = |s: String| {
        if !out.contains(&s) {
            out.push(s);
        }
    };
    match tool {
        Tool::Claude => {
            set.shell.iter().for_each(|x| push(format!("Bash({x}:*)")));
            set.shell_glob
                .iter()
                .for_each(|x| push(format!("Bash({x}*)")));
            set.shell_exact
                .iter()
                .for_each(|x| push(format!("Bash({x})")));
            set.read.iter().for_each(|x| push(format!("Read(/{x})")));
            set.mcp
                .iter()
                .for_each(|x| push(format!("mcp__{}", x.replacen('/', "__", 1))));
            set.claude.iter().for_each(|x| push(x.clone()));
        }
        Tool::Agy => {
            set.shell
                .iter()
                .chain(&set.shell_glob)
                .chain(&set.shell_exact)
                .for_each(|x| push(format!("command({x})")));
            set.read
                .iter()
                .for_each(|x| push(format!("read_file({x})")));
            set.mcp.iter().for_each(|x| push(format!("mcp({x})")));
            set.agy.iter().for_each(|x| push(x.clone()));
        }
    }
    out
}

/// Parse one native permission entry back into a neutral slot (for `import`/`promote`).
/// Returns (slot, value); unknown shapes land in the tool's raw slot.
pub fn parse_perm(entry: &str, tool: Tool) -> (&'static str, String) {
    let raw = (tool.key(), entry.to_string());
    match tool {
        Tool::Claude => {
            if let Some(inner) = entry
                .strip_prefix("Bash(")
                .and_then(|r| r.strip_suffix(')'))
            {
                if let Some(x) = inner.strip_suffix(":*") {
                    return ("shell", x.to_string());
                }
                if let Some(x) = inner.strip_suffix('*') {
                    return ("shell_glob", x.to_string());
                }
                return ("shell_exact", inner.to_string());
            }
            if let Some(p) = entry
                .strip_prefix("Read(/")
                .and_then(|r| r.strip_suffix(')'))
                .filter(|p| p.starts_with('/'))
            {
                return ("read", p.to_string());
            }
            if let Some(rest) = entry.strip_prefix("mcp__") {
                // Splits on the FIRST `__`: assumes server names contain no `__` (true of every
                // server in mcp.toml); `mcp__a__b__tool` would parse as server `a`.
                return ("mcp", rest.replacen("__", "/", 1));
            }
            raw
        }
        Tool::Agy => {
            // AGY has no prefix/exact distinction, so the reverse mapping is lossy. Resolve it
            // toward LEAST privilege: `command(X)` promotes to Claude's exact `Bash(X)`, never the
            // wider prefix `Bash(X:*)` (which would also grant `X <anything>`).
            if let Some(x) = entry
                .strip_prefix("command(")
                .and_then(|r| r.strip_suffix(')'))
            {
                return ("shell_exact", x.to_string());
            }
            if let Some(p) = entry
                .strip_prefix("read_file(")
                .and_then(|r| r.strip_suffix(')'))
            {
                return ("read", p.to_string());
            }
            if let Some(x) = entry.strip_prefix("mcp(").and_then(|r| r.strip_suffix(')')) {
                return ("mcp", x.to_string());
            }
            raw
        }
    }
}

/// Claude `settings.json` `.hooks`: events in first-seen order; consecutive hooks sharing an
/// event+matcher merge into one entry, as Claude writes them.
pub fn render_claude_hooks(hooks: &HookFile) -> Value {
    let mut events: Map<String, Value> = Map::new();
    for h in &hooks.hooks {
        let Some(side) = &h.claude else { continue };
        let event = side.event.clone().unwrap_or_else(|| h.event.clone());
        let mut hook = Map::new();
        hook.insert("type".into(), json!("command"));
        hook.insert(
            "command".into(),
            json!(side.command.clone().unwrap_or_else(|| h.command.clone())),
        );
        if let Some(t) = side.timeout {
            hook.insert("timeout".into(), json!(t));
        }
        let list = events
            .entry(event)
            .or_insert_with(|| Value::Array(vec![]))
            .as_array_mut();
        let Some(list) = list else { continue };
        // None == None covers the matcher-less events (UserPromptSubmit).
        let same_matcher = list.last().is_some_and(|last| {
            last.get("matcher").and_then(Value::as_str) == side.matcher.as_deref()
        });
        if same_matcher {
            if let Some(arr) = list
                .last_mut()
                .and_then(|l| l.get_mut("hooks"))
                .and_then(Value::as_array_mut)
            {
                arr.push(Value::Object(hook));
                continue;
            }
        }
        let mut entry = Map::new();
        if let Some(m) = &side.matcher {
            entry.insert("matcher".into(), json!(m));
        }
        entry.insert("hooks".into(), json!([Value::Object(hook)]));
        list.push(Value::Object(entry));
    }
    Value::Object(events)
}

/// AGY `~/.gemini/config/hooks.json`: `{ "<hook name>": { "<Event>": [ … ] } }`.
pub fn render_agy_hooks(hooks: &HookFile) -> Value {
    let mut out = Map::new();
    for h in &hooks.hooks {
        let Some(side) = &h.agy else { continue };
        let event = side.event.clone().unwrap_or_else(|| h.event.clone());
        let mut cmd = Map::new();
        cmd.insert("type".into(), json!("command"));
        cmd.insert(
            "command".into(),
            json!(side.command.clone().unwrap_or_else(|| h.command.clone())),
        );
        if let Some(t) = side.timeout {
            cmd.insert("timeout".into(), json!(t));
        }
        let entry = match &side.matcher {
            Some(m) => json!({ "matcher": m, "hooks": [Value::Object(cmd)] }),
            None => Value::Object(cmd),
        };
        out.insert(h.name.clone(), json!({ event: [entry] }));
    }
    Value::Object(out)
}

/// Codex `~/.codex/hooks.json` wraps the event map under a top-level `hooks` key.
pub fn render_codex_hooks(hooks: &HookFile) -> Value {
    let mut events: Map<String, Value> = Map::new();
    for h in &hooks.hooks {
        let Some(side) = &h.codex else { continue };
        let event = side.event.clone().unwrap_or_else(|| h.event.clone());
        let mut handler = Map::new();
        handler.insert("type".into(), json!("command"));
        handler.insert(
            "command".into(),
            json!(side.command.clone().unwrap_or_else(|| h.command.clone())),
        );
        if let Some(t) = side.timeout {
            handler.insert("timeout".into(), json!(t));
        }
        let list = events
            .entry(event)
            .or_insert_with(|| Value::Array(vec![]))
            .as_array_mut();
        let Some(list) = list else { continue };
        let same_matcher = list.last().is_some_and(|last| {
            last.get("matcher").and_then(Value::as_str) == side.matcher.as_deref()
        });
        if same_matcher {
            if let Some(arr) = list
                .last_mut()
                .and_then(|l| l.get_mut("hooks"))
                .and_then(Value::as_array_mut)
            {
                arr.push(Value::Object(handler));
                continue;
            }
        }
        let mut entry = Map::new();
        if let Some(m) = &side.matcher {
            entry.insert("matcher".into(), json!(m));
        }
        entry.insert("hooks".into(), json!([Value::Object(handler)]));
        list.push(Value::Object(entry));
    }
    json!({ "hooks": Value::Object(events) })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{Hook, HookSide};

    fn map() -> MapFile {
        toml::from_str(
            r#"
            placeholders = ["SERVER_IP"]
            [tiers.claude]
            fast = "haiku"
            standard = "sonnet"
            [tiers.agy]
            fast = "flash"
            standard = "pro"
            [tools.claude]
            shell = "Bash"
            read = "Read"
            grep = "Grep"
            [tools.agy]
            shell = "run_command"
            read = "view_file"
            grep = "run_command"
            "#,
        )
        .unwrap()
    }

    #[test]
    fn only_blocks_filter_per_tool() {
        let body =
            "a\n<!-- only:claude -->\nc\n<!-- /only -->\n<!-- only:agy -->\ng\n<!-- /only -->\nz\n";
        assert_eq!(filter_only(body, Tool::Claude).unwrap(), "a\nc\nz\n");
        assert_eq!(filter_only(body, Tool::Agy).unwrap(), "a\ng\nz\n");
        assert!(filter_only("<!-- only:claude -->\nx\n", Tool::Claude).is_err());
        assert!(filter_only("<!-- /only -->\n", Tool::Claude).is_err());
    }

    #[test]
    fn agent_renders_natively_for_each_tool() {
        let a = Agent::parse(
            "---\nname: r\ndescription: \"Use: to review\"\ntier: standard\ntools: [read, grep, shell, \"mcp:example-server\"]\nclaude:\n  maxTurns: 80\n  color: orange\n---\nbody\n",
        )
        .unwrap();
        let c = render_agent(&map(), &a, Tool::Claude).unwrap();
        assert!(c.contains("tools: Read, Grep, Bash, mcp__example-server\nmodel: sonnet\nmaxTurns: 80\ncolor: orange\n"));
        let g = render_agent(&map(), &a, Tool::Agy).unwrap();
        assert!(g.contains(
            "model: pro\nenable_mcp_tools: true\ntools:\n  - view_file\n  - run_command\n---\n"
        ));
        assert!(!g.contains("maxTurns"));
        // Both front matters parse strictly.
        for out in [c, g] {
            let (yaml, _) = crate::model::split_front_matter(&out).unwrap();
            let v: serde_yaml::Value = serde_yaml::from_str(yaml).unwrap();
            assert_eq!(v["description"].as_str(), Some("Use: to review"));
        }
    }

    #[test]
    fn placeholders_expand_only_allow_listed_names() {
        let lookup = |n: &str| match n {
            "SERVER_IP" => Some("198.51.100.5".to_string()),
            "MY_API_TOKEN" => Some("SECRET-VALUE".to_string()),
            _ => None,
        };
        let allowed = vec!["SERVER_IP".to_string()];
        let s = "http://${SERVER_IP}:9090 --header \"Authorization:${MY_API_TOKEN}\"";
        let out = expand_placeholders(s, &allowed, &lookup).unwrap();
        assert_eq!(
            out,
            "http://198.51.100.5:9090 --header \"Authorization:${MY_API_TOKEN}\""
        );
        assert!(!out.contains("SECRET-VALUE"));
        // An allow-listed but unset name is an error, never an empty string.
        let none = |_: &str| None;
        assert!(expand_placeholders("${SERVER_IP}", &allowed, &none).is_err());
    }

    #[test]
    fn perms_round_trip_both_tools() {
        let claude = [
            "Bash(git status:*)",
            "Bash(find*)",
            "Bash(env)",
            "Read(//var/lib/app/token)",
            "mcp__files__read_logs",
            "WebFetch(domain:x)",
        ];
        let mut set = PermSet::default();
        for e in claude {
            let (slot, v) = parse_perm(e, Tool::Claude);
            match slot {
                "shell" => set.shell.push(v),
                "shell_glob" => set.shell_glob.push(v),
                "shell_exact" => set.shell_exact.push(v),
                "read" => set.read.push(v),
                "mcp" => set.mcp.push(v),
                _ => set.claude.push(v),
            }
        }
        assert_eq!(render_perms(&set, Tool::Claude), claude);
        assert_eq!(
            render_perms(&set, Tool::Agy),
            [
                "command(git status)",
                "command(find)",
                "command(env)",
                "read_file(/var/lib/app/token)",
                "mcp(files/read_logs)"
            ]
        );
    }

    #[test]
    fn http_server_renders_per_tool_and_validates() {
        let srv: McpServer = toml::from_str(
            "url = \"http://127.0.0.1:${PORT}/mcp\"\nagents = [\"claude\", \"agy\"]\n",
        )
        .unwrap();
        srv.validate("g").unwrap();
        let allowed = vec!["PORT".to_string()];
        let lookup = |n: &str| (n == "PORT").then(|| "18765".to_string());
        let c = render_mcp_server(&srv, Tool::Claude, &allowed, &lookup).unwrap();
        assert_eq!(
            c,
            json!({"type": "http", "url": "http://127.0.0.1:18765/mcp"})
        );
        let g = render_mcp_server(&srv, Tool::Agy, &allowed, &lookup).unwrap();
        assert_eq!(g, json!({"serverUrl": "http://127.0.0.1:18765/mcp"}));
        // Neither or both transports, or process fields on a url server, are rejected.
        let bad: McpServer = toml::from_str("agents = [\"agy\"]\n").unwrap();
        assert!(bad.validate("x").is_err());
        let both: McpServer = toml::from_str("command = \"a\"\nurl = \"b\"\n").unwrap();
        assert!(both.validate("x").is_err());
        let args: McpServer = toml::from_str("url = \"b\"\nargs = [\"-v\"]\n").unwrap();
        assert!(args.validate("x").is_err());
    }

    #[test]
    fn agy_promotion_is_least_privilege() {
        assert_eq!(
            parse_perm("command(rm -rf /tmp/foo)", Tool::Agy),
            ("shell_exact", "rm -rf /tmp/foo".to_string())
        );
        let set = PermSet {
            shell_exact: vec!["rm -rf /tmp/foo".into()],
            ..Default::default()
        };
        assert_eq!(render_perms(&set, Tool::Claude), ["Bash(rm -rf /tmp/foo)"]);
    }

    #[test]
    fn claude_hooks_merge_same_matcher_and_omit_absent_matcher() {
        let side = |m: Option<&str>| HookSide {
            matcher: m.map(String::from),
            timeout: Some(10),
            ..Default::default()
        };
        let hf = HookFile {
            hooks: vec![
                Hook {
                    name: "a".into(),
                    event: "PreToolUse".into(),
                    command: "x".into(),
                    claude: Some(side(Some("Bash"))),
                    agy: Some(side(Some("run_command"))),
                    codex: None,
                },
                Hook {
                    name: "b".into(),
                    event: "PreToolUse".into(),
                    command: "y".into(),
                    claude: Some(side(Some("Bash"))),
                    agy: None,
                    codex: None,
                },
                Hook {
                    name: "c".into(),
                    event: "UserPromptSubmit".into(),
                    command: "z".into(),
                    claude: Some(side(None)),
                    agy: None,
                    codex: None,
                },
            ],
        };
        let c = render_claude_hooks(&hf);
        assert_eq!(c["PreToolUse"].as_array().unwrap().len(), 1);
        assert_eq!(c["PreToolUse"][0]["hooks"].as_array().unwrap().len(), 2);
        assert!(c["UserPromptSubmit"][0].get("matcher").is_none());
        let g = render_agy_hooks(&hf);
        assert_eq!(g.as_object().unwrap().len(), 1);
        assert_eq!(g["a"]["PreToolUse"][0]["matcher"], "run_command");
    }

    #[test]
    fn validate_frontmatter_catches_invalid_tools() {
        let bad_agy = r#"
name: test-agent
description: "Test agent"
model: pro
tools:
  - call_mcp_tool
"#;
        assert!(validate_agent_frontmatter(bad_agy, Tool::Agy).is_err());

        let good_agy = r#"
name: test-agent
description: "Test agent"
model: pro
enable_mcp_tools: true
tools:
  - run_command
  - view_file
"#;
        assert!(validate_agent_frontmatter(good_agy, Tool::Agy).is_ok());

        let bad_claude = r#"
name: test-agent
description: "Test agent"
model: sonnet
tools: run_command, view_file
"#;
        assert!(validate_agent_frontmatter(bad_claude, Tool::Claude).is_err());

        let good_claude = r#"
name: test-agent
description: "Test agent"
model: sonnet
tools: Bash, Read, mcp__example-server
"#;
        assert!(validate_agent_frontmatter(good_claude, Tool::Claude).is_ok());
    }
}
